//
// test_header.c — SYMMETRY unit test of the protocol v3 header (C side).
//
// Checks that protocol_v3.h packs/unpacks the header exactly like the vectors
// in header_vectors.h, generated by the independent Python reference
// (tools/check_header.py): if the C code deviates, the test fails.
//
// It is written to run on the HOST too (gcc), so the symmetry is checked
// without flashing the ESP32:
//     gcc -I ../include test_header.c -o test_header && ./test_header
//
#include <stdio.h>
#include "protocol_v3.h"
#include "header_vectors.h"

int main(void) {
    int failures = 0;

    for (int i = 0; i < HEADER_VECTORS_N; i++) {
        const header_vec_t *v = &HEADER_VECTORS[i];

        // 1) Packing: hdr_pack -> big-endian bytes must match the vectors.
        uint32_t h = hdr_pack(v->pktId, v->flags, v->idx, v->cnt, v->bitmask);
        uint8_t b[4] = {
            (uint8_t)((h >> 24) & 0xFF), (uint8_t)((h >> 16) & 0xFF),
            (uint8_t)((h >> 8) & 0xFF),  (uint8_t)(h & 0xFF)
        };
        if (b[0] != v->bytes[0] || b[1] != v->bytes[1] ||
            b[2] != v->bytes[2] || b[3] != v->bytes[3]) {
            printf("[FAIL] vector %d: packed bytes differ "
                   "(expected %02X %02X %02X %02X, got %02X %02X %02X %02X)\n",
                   i, v->bytes[0], v->bytes[1], v->bytes[2], v->bytes[3],
                   b[0], b[1], b[2], b[3]);
            failures++;
            continue;
        }

        // 2) Unpacking: be32_read + hdr_* must rebuild the original fields.
        uint32_t hr = be32_read(v->bytes);
        if (hdr_pktId(hr) != v->pktId || hdr_flags(hr) != v->flags ||
            hdr_idx(hr) != v->idx || hdr_cnt(hr) != v->cnt ||
            hdr_bitmask(hr) != v->bitmask) {
            printf("[FAIL] vector %d: unpacked fields differ\n", i);
            failures++;
        }
    }

    if (failures == 0) {
        printf("[OK] %d header vectors: symmetric packing/unpacking\n",
               HEADER_VECTORS_N);
        return 0;
    }
    printf("[KO] %d vectors failed out of %d\n", failures, HEADER_VECTORS_N);
    return 1;
}
